import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:provider/provider.dart';import '../../models/author.dart';import '../../repositories/author_repository.dart';
class AuthorDetailScreen extends StatelessWidget{final int authorId;const AuthorDetailScreen({super.key,required this.authorId});@override Widget build(BuildContext c)=>FutureBuilder<Author?>(future:c.read<AuthorRepository>().findById(authorId),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final a=s.data;if(a==null)return const Center(child:Text('Автор не найден'));return Scaffold(appBar:AppBar(title:const Text('Карточка автора'),actions:[IconButton(icon:const Icon(Icons.edit),onPressed:()=>c.go('/authors/${a.id}/edit'))]),body:ListView(padding:const EdgeInsets.all(20),children:[Text(a.fullName,style:Theme.of(c).textTheme.headlineMedium),Card(child:ListTile(title:const Text('Год рождения'),subtitle:Text('${a.birthYear}'))),Card(child:ListTile(title:const Text('Страна'),subtitle:Text(a.country)))]));});}
